<?php
require_once __DIR__ . '/../config/app.php'; require_admin();
$pageTitle='Kelola Pengguna';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($id===(int)current_user()['id'])$error='Admin tidak dapat mengubah atau menghapus akunnya sendiri dari halaman ini.';elseif($action==='delete'){$q=$pdo->prepare("SELECT COUNT(*) FROM transactions WHERE user_id=?");$q->execute([$id]);if((int)$q->fetchColumn())$error='Pengguna memiliki riwayat transaksi. Akun tidak dapat dihapus.';else{$q=$pdo->prepare("DELETE FROM users WHERE id=? AND role='user'");$q->execute([$id]);set_flash('success','Pengguna dihapus.');redirect('/admin/users.php');}}else{$role=$_POST['role']??'user';if(!in_array($role,['user','admin'],true))$role='user';$q=$pdo->prepare("UPDATE users SET role=? WHERE id=? AND role IN ('user','admin')");$q->execute([$role,$id]);set_flash('success','Role pengguna diperbarui.');redirect('/admin/users.php');}}
$users=$pdo->query('SELECT u.id,u.name,u.email,u.role,u.created_at,COUNT(t.id) order_count FROM users u LEFT JOIN transactions t ON t.user_id=u.id GROUP BY u.id ORDER BY u.created_at DESC')->fetchAll();
require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><span class="eyebrow">ADMIN / AKUN</span><h1>Kelola Pengguna</h1><p class="muted">Pendaftaran akun dilakukan melalui halaman Register.</p></div><a class="text-link" href="<?=BASE_URL?>/admin/index.php">← Dashboard</a></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="panel table-wrap"><table><thead><tr><th>Nama / Email</th><th>Role</th><th>Transaksi</th><th>Terdaftar</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?><br><small><?=e($u['email'])?></small></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><select name="role"><option value="user" <?=$u['role']==='user'?'selected':''?>>User</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option></select><button class="btn btn-small" name="action" value="role">Simpan</button></form></td><td><?=(int)$u['order_count']?></td><td><?=e($u['created_at'])?></td><td><form method="post" class="inline-form" onsubmit="return confirm('Hapus pengguna ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><button class="danger-link" name="action" value="delete">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
